// Builds the background presets: `bun run backgrounds`.
//
// Source: one folder per preset in backgrounds/ (git-ignored, the originals
// are large), holding one or two pictures of any name and format plus an
// optional meta.json with display names: { "name": { "en": "...", "tr": "..." } }.
// matugen decides whether each picture is light or dark, so a preset can
// have a light variant (shown in the light theme), a dark one (dark theme),
// or both; with only one, it is shown in either theme.
//
// Output (all generated, do not edit by hand):
//   public/backgrounds/<id>-<variant>.webp and -thumb.webp
//   src/generated/backgrounds.json  presets listed in the settings
//   src/generated/backgrounds.css   `data-bg-image` rules, so the pre-paint
//                                   script in index.html only sets an attribute
//
// Needs `magick` (ImageMagick) and `matugen` on PATH.

import { execFileSync } from "node:child_process";
import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  rmSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { extname, join, resolve } from "node:path";

type Variant = "light" | "dark";
type Names = Record<string, string>;
type Preset = {
  id: string;
  name: Names;
  // Average color per variant, painted until the picture has loaded.
  light?: string;
  dark?: string;
};

const root = resolve(import.meta.dirname, "..");
const sourceDir = join(root, "backgrounds");
const outputDir = join(root, "public", "backgrounds");
const generatedDir = join(root, "src", "generated");

const pictureExtensions = new Set([".png", ".jpg", ".jpeg", ".webp", ".avif"]);
const idPattern = /^[a-z0-9]+(-[a-z0-9]+)*$/;

function run(command: string, args: string[]): string {
  return execFileSync(command, args, { encoding: "utf8", maxBuffer: 64 << 20 });
}

function variantOf(picture: string): Variant {
  const output = run("matugen", [
    "image",
    picture,
    "--mode",
    "smart",
    "--source-color-index",
    "0",
    "--json",
    "hex",
    "--dry-run",
    "--quiet",
  ]);
  const scheme = JSON.parse(output) as { is_dark_mode: boolean };
  return scheme.is_dark_mode ? "dark" : "light";
}

function averageColor(picture: string): string {
  const hex = run("magick", [
    picture,
    "-resize",
    "64x64!",
    "-scale",
    "1x1!",
    "-depth",
    "8",
    "-format",
    "%[hex:p{0,0}]",
    "info:",
  ]).trim();
  return `#${hex.slice(0, 6).toLowerCase()}`;
}

function convert(picture: string, id: string, variant: Variant) {
  const base = join(outputDir, `${id}-${variant}`);
  // Never upscales; 2560 wide is plenty under translucent surfaces.
  run("magick", [
    picture, "-auto-orient", "-strip", "-resize", "2560x1440^>",
    "-quality", "80", `${base}.webp`,
  ]);
  run("magick", [
    picture, "-auto-orient", "-strip", "-resize", "320x180^",
    "-gravity", "center", "-extent", "320x180", "-quality", "75",
    `${base}-thumb.webp`,
  ]);
}

function readNames(dir: string, id: string): Names {
  const fallback = { en: id.charAt(0).toUpperCase() + id.slice(1) };
  const file = join(dir, "meta.json");
  if (!existsSync(file)) return fallback;
  const meta = JSON.parse(readFileSync(file, "utf8")) as { name?: Names };
  return { ...fallback, ...meta.name };
}

function buildPreset(id: string): Preset {
  const dir = join(sourceDir, id);
  const pictures = readdirSync(dir)
    .filter((file) => pictureExtensions.has(extname(file).toLowerCase()))
    .map((file) => join(dir, file));
  if (pictures.length === 0 || pictures.length > 2) {
    throw new Error(`${id}: expected one or two pictures, found ${pictures.length}`);
  }

  const preset: Preset = { id, name: readNames(dir, id) };
  for (const picture of pictures) {
    const variant = variantOf(picture);
    if (preset[variant]) {
      throw new Error(`${id}: both pictures are ${variant}; matugen saw no ${variant === "light" ? "dark" : "light"} one`);
    }
    convert(picture, id, variant);
    preset[variant] = averageColor(picture);
    console.log(`  ${id}: ${variant} ${preset[variant]}`);
  }
  return preset;
}

function imageRule(selector: string, id: string, variant: Variant, tint: string) {
  return `    ${selector} { --app-bg-tint: ${tint}; --app-bg-image: url("/backgrounds/${id}-${variant}.webp"); }`;
}

function css(presets: Preset[]): string {
  const rules: string[] = [];
  for (const { id, light, dark } of presets) {
    // The light rule is the default; a lone dark picture covers both themes.
    const base: Variant = light ? "light" : "dark";
    rules.push(imageRule(`:root[data-bg-image="${id}"]`, id, base, (light ?? dark)!));
    if (light && dark) {
      rules.push(imageRule(`:root.dark[data-bg-image="${id}"]`, id, "dark", dark));
    }
  }
  return `/* Generated by scripts/backgrounds.ts; do not edit. */
@layer theme {
${rules.join("\n")}
}
`;
}

const ids = readdirSync(sourceDir)
  .filter((entry) => statSync(join(sourceDir, entry)).isDirectory())
  .sort();
for (const id of ids) {
  if (!idPattern.test(id)) throw new Error(`${id}: use lowercase letters, digits and dashes`);
}

// Empties the folder rather than recreating it: a running Vite dev server
// stops serving a public/ folder that was deleted under it.
mkdirSync(outputDir, { recursive: true });
for (const file of readdirSync(outputDir)) {
  rmSync(join(outputDir, file), { recursive: true, force: true });
}
mkdirSync(generatedDir, { recursive: true });

console.log(`Building ${ids.length} background presets`);
const presets = ids.map(buildPreset);

writeFileSync(join(generatedDir, "backgrounds.json"), `${JSON.stringify(presets, null, 2)}\n`);
writeFileSync(join(generatedDir, "backgrounds.css"), css(presets));
console.log("Wrote public/backgrounds/ and src/generated/backgrounds.{json,css}");
